   139	                        p = ERROR_STR;
   140	                addf(str, "%sIPAddress: %s\n", prefix, p);
   141	                break;
   142	
   143	        case GNUTLS_SAN_DN:
   144	                addf(str,  _("%sdirectoryName: %.*s\n"), prefix, name->size, NON_NULL(name->data));
   145	                break;
   146	
   147	        case GNUTLS_SAN_OTHERNAME_XMPP:
