    90	                                addf(str,  _("%s%s: %.*s (%s)\n"), prefix, type, name->size, NON_NULL(name->data), out.data);
    91	                                is_printed = 1;
    92	                                gnutls_free(out.data);
    93	                        }
    94	                }
    95	        }
    96	
    97	        if (is_printed == 0) {
    98	                addf(str,  _("%s%s: %.*s\n"), prefix, type, name->size, NON_NULL(name->data));
    99	        }
   100	}
